css:
@font-face {
	font-family: "THSarabun";
	src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf") format("truetype");
}

@page {
	size: A4 landscape;
	margin: 0;
}

* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}

html,
body {
	margin: 0;
	padding: 0;
	width: 297mm;
	height: 210mm;
}

body {
	font-family:
		"THSarabun", "Sarabun", "TH Sarabun New", "Noto Sans Thai", Arial,
		sans-serif;
	font-size: 9pt;
	color: #111;
}

.print-format,
.print-format-preview {
	padding: 0 !important;
	margin: 0 !important;
	margin-top: 0mm !important;
	margin-bottom: 0mm !important;
	margin-left: 0mm !important;
	margin-right: 0mm !important;
	min-height: unset !important;
	max-width: unset !important;
	page-size: A4;
	orientation: Landscape;
}

.page {
	position: relative;
	overflow: hidden;
	page-break-after: always;
	background-repeat: no-repeat;
	color: #111;
}

.page:last-child {
	page-break-after: auto;
}

.page.wht-page {
	width: 297mm;
	height: 210mm;
	background-size: 297mm 210mm;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-size: 7pt;
}

.page.wht-page.wht-pv {
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/wht_pv6904003_1.jpg?v=20260603-jpgpdf1");
}

.page.wht-page.wht-jv {
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/wht_jv6904003_01_1.jpg?v=20260603-jpgpdf1");
}

.f,
.field {
	position: absolute;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-size: 7pt;
	font-weight: 400;
	line-height: 1.08;
	color: #111;
	white-space: nowrap;
}

.amount,
.text-right,
.tr {
	text-align: right;
	font-variant-numeric: tabular-nums;
	white-space: nowrap;
}

.tc {
	text-align: center;
}

.nowrap {
	white-space: nowrap;
	overflow: hidden;
}

.small {
	font-size: 7pt;
	font-weight: 400;
}

table {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}

td {
	padding: 0.8mm 1mm;
	vertical-align: top;
	line-height: 1.05;
	word-break: break-word;
}

.payer-mark,
.amount-words,
.income-desc,
.issue-date {
	font-size: 7pt;
	font-weight: 400;
}

html:
{%- set bg_class = "wht-jv" if (doc.get("voucher_no") or "").startswith("JV") else "wht-pv" -%}
{%- macro d(value) -%}{%- if value -%}{{ frappe.format_date(value, "dd/MM/yyyy") }}{%- endif -%}{%- endmacro -%}
{%- set total_tax_base = (doc.get("withholding_tax_items") or []) | sum(attribute="tax_base") -%}
{%- set total_tax_amount = (doc.get("withholding_tax_items") or []) | sum(attribute="tax_amount") -%}
{%- macro render_side(x) -%}
  <div class="f" style="top: 17.2mm; left: {{ x + 17 }}mm; width: 28mm;">{{ (doc.get("name") or "").split("-")[-1] }}</div>
  <div class="f tr" style="top: 17.5mm; left: {{ x + 101 }}mm; width: 30mm;">{{ doc.get("voucher_no") or "" }}</div>
  <div class="f tr" style="top: 25mm; left: {{ x + 94 }}mm; width: 35mm;">{{ doc.get("company_tax_id") or "" }}</div>
  <div class="f" style="top: 42mm; left: {{ x + 18 }}mm; width: 56mm;">{{ doc.get("supplier_name") or doc.get("supplier") or "" }}</div>
  <div class="f tr" style="top: 38mm; left: {{ x + 94 }}mm; width: 35mm;">{{ doc.get("supplier_tax_id") or "" }}</div>
  <div class="f" style="top: 45.8mm; left: {{ x + 18 }}mm; width: 113mm;">{{ doc.get("supplier_address_display") or doc.get("supplier_address") or "" }}</div>
  {%- for item in doc.get("withholding_tax_items") or [] -%}
    {%- if loop.index <= 3 -%}
      <div class="f income-desc" style="top: {{ 136.5 + loop.index0 * 8 }}mm; left: {{ x + 33 }}mm; width: 80mm;">{{ item.get("description") or item.get("type_of_income") or "" }}</div>
      <div class="f tc" style="top: {{ 137.5 + loop.index0 * 8 }}mm; left: {{ x + 95 }}mm; width: 18mm;">{{ d(doc.get("date")) }}</div>
      <div class="f tr" style="top: {{ 137.5 + loop.index0 * 8 }}mm; left: {{ x + 109 }}mm; width: 15.5mm;">{{ print_currency(item.get("tax_base") or 0) }}</div>
      <div class="f tr" style="top: {{ 137.5 + loop.index0 * 8 }}mm; left: {{ x + 127 }}mm; width: 13.8mm;">{{ print_currency(item.get("tax_amount") or 0) }}</div>
    {%- endif -%}
  {%- endfor -%}
  <div class="f tr" style="top: 142mm; left: {{ x + 109 }}mm; width: 15.5mm;">{{ print_currency(total_tax_base) }}</div>
  <div class="f tr" style="top: 142mm; left: {{ x + 127 }}mm; width: 13.8mm;">{{ print_currency(total_tax_amount) }}</div>
  <div class="f amount-words" style="top: 146mm; left: {{ x + 35 }}mm; width: 56mm;">({{ number_to_thai_currency(total_tax_amount) }}).</div>
  <div class="f payer-mark" style="top: 151.8mm; left: {{ x + 42.6 }}mm; width: 4mm;">{% if doc.get("tax_payer") == "Withholding" %}X{% endif %}</div>
  <div class="f payer-mark" style="top: 151.8mm; left: {{ x + 87.6 }}mm; width: 4mm;">{% if doc.get("tax_payer") == "Paid One Time" %}X{% endif %}</div>
  <div class="f issue-date" style="top: 179mm; left: {{ x + 62 }}mm; width: 30mm;">{{ d(doc.get("date")) }}</div>
{%- endmacro -%}
<div class="page wht-page {{ bg_class }}">
  {{ render_side(0) }}
  {{ render_side(148.5) }}
</div>
